    'MS Billing Documentation': 'MS బిల్లింగ్ డాక్యుమెంటేషన్',
    'Comprehensive guide to managing your restaurant': 'మీ రెస్టారెంట్ నిర్వహణకు సమగ్ర గైడ్',
    'Welcome to MS Billing': 'MS బిల్లింగ్‌కు స్వాగతం',
    'MS Billing is a next-generation Restaurant Management POS designed for speed, accuracy, and ease of use. Whether you are running a small cafe or a multi-floor fine dining restaurant, this guide will help you get the most out of your terminal.': 'MS బిల్లింగ్ అనేది వేగం, ఖచ్చితత్వం మరియు వాడుకలో సౌలభ్యం కోసం రూపొందించబడిన తదుపరి తరం రెస్టారెంట్ నిర్వహణ POS.మీరు చిన్న కేఫ్ లేదా మల్టీ-ఫ్లోర్ ఫైన్ డైనింగ్ రెస్టారెంట్ నడుపుతున్నా, మీ టెర్మినల్ నుండి ఎక్కువ ప్రయోజనం పొందడానికి ఈ గైడ్ మీకు సహాయం చేస్తుంది.',
    'Quick Setup': 'త్వరిత సెటప్',
    'Create your spaces (Tables, Cabins, Sofas) in Floor Management.': 'ఫ్లోర్ మేనేజ్‌మెంట్‌లో మీ ఖాళీలను (టేబుల్‌లు, క్యాబిన్‌లు, సోఫాలు) సృష్టించండి.',
    'Add your categories and food items in the Menu Management.': 'మెనూ మేనేజ్‌మెంట్‌లో మీ వర్గాలను మరియు ఆహార పదార్థాలను జోడించండి.',
    'Register your staff members with Face AI for seamless attendance.': 'అతుకులు లేని హాజరు కోసం మీ సిబ్బందిని ఫేస్ AIతో నమోదు చేసుకోండి.',
    'You are ready to start taking orders!': 'మీరు ఆర్డర్లు తీసుకోవడం ప్రారంభించడానికి సిద్ధంగా ఉన్నారు!',
