    'tab.                       Select the items from the menu, adjust quantities using the + and - buttons, and click': 'ట్యాబ్. మెను నుండి ఐటెమ్‌లను ఎంచుకుని, + మరియు - బటన్‌లను ఉపయోగించి పరిమాణాలను సర్దుబాటు చేసి, క్లిక్ చేయండి',
