    'Click on a cart item to add special instructions (e.g., "Less spicy").': 'ప్రత్యేక సూచనలను జోడించడానికి కార్ట్ ఐటెమ్‌పై క్లిక్ చేయండి (ఉదా., "తక్కువ కారంగా").',
