    'The Floor Management screen is your bird\'s-eye view of the restaurant. Colors indicate table status:': 'ఫ్లోర్ మేనేజ్‌మెంట్ స్క్రీన్ రెస్టారెంట్ యొక్క మీ పక్షి వీక్షణ.రంగులు పట్టిక స్థితిని సూచిస్తాయి:',
    'Occupied': 'ఆక్రమించబడింది',
    'Bill Printed': 'బిల్లు ముద్రించబడింది',
    'Managing Spaces': 'ఖాళీలను నిర్వహించడం',
    'As an Admin, you can add new Spaces (like "AC Section", "Rooftop") and configure how many tables belong to each space from the Settings menu.': 'అడ్మిన్‌గా, మీరు కొత్త స్పేస్‌లను జోడించవచ్చు ("AC విభాగం", "రూఫ్‌టాప్" వంటివి) మరియు సెట్టింగ్‌ల మెను నుండి ప్రతి స్పేస్‌కు ఎన్ని టేబుల్‌లు చెందాలో కాన్ఫిగర్ చేయవచ్చు.',
