    'Facial Recognition Setup': 'ఫేషియల్ రికగ్నిషన్ సెటప్',
    'MS Billing features a state-of-the-art AI Face Recognition system for staff clock-ins to prevent buddy-punching.': 'MS బిల్లింగ్ బడ్డీ-పంచింగ్‌ను నిరోధించడానికి స్టాఫ్ క్లాక్-ఇన్‌ల కోసం స్టేట్ ఆఫ్ ది ఆర్ట్ AI ఫేస్ రికగ్నిషన్ సిస్టమ్‌ను కలిగి ఉంది.',
    'Go to': 'వెళ్ళండి',
    'Staff HR': 'సిబ్బంది HR',
    'Click': 'క్లిక్ చేయండి',
    'and fill in their details (Name, Role, PIN).': 'మరియు వారి వివరాలను పూరించండి (పేరు, పాత్ర, పిన్).',
    'Click the Camera icon next to their profile to capture their facial biometrics.': 'వారి ముఖ బయోమెట్రిక్‌లను క్యాప్చర్ చేయడానికి వారి ప్రొఫైల్ పక్కన ఉన్న కెమెరా చిహ్నాన్ని క్లిక్ చేయండి.',
    'They can now use the': 'వారు ఇప్పుడు ఉపయోగించవచ్చు',
    'AI Clock-In': 'AI క్లాక్-ఇన్',
    'button on the login screen to start their shift!': 'వారి షిఫ్ట్‌ని ప్రారంభించడానికి లాగిన్ స్క్రీన్‌పై బటన్!',
    'Reports & Analytics': 'నివేదికలు & విశ్లేషణలు',
    'Make data-driven decisions with real-time insights into your business performance.': 'మీ వ్యాపార పనితీరుపై నిజ-సమయ అంతర్దృష్టులతో డేటా ఆధారిత నిర్ణయాలు తీసుకోండి.',
    'View daily cash flow, total sales, expenses, and net profit at a glance.': 'రోజువారీ నగదు ప్రవాహం, మొత్తం అమ్మకాలు, ఖర్చులు మరియు నికర లాభాన్ని ఒక చూపులో వీక్షించండి.',
    'Analytics Dashboard': 'Analytics డాష్‌బోర్డ్',
    'Deep dive into Top Selling Items, Revenue by Time, and Payment Methods breakdowns.': 'అత్యధికంగా అమ్ముడవుతున్న వస్తువులు, సమయానుగుణంగా రాబడి మరియు చెల్లింపు పద్ధతుల బ్రేక్‌డౌన్‌ల గురించి లోతుగా డైవ్ చేయండి.',
    'System Settings': 'సిస్టమ్ సెట్టింగ్‌లు',
    'Admin Only Access': 'అడ్మిన్ మాత్రమే యాక్సెస్',
    'The Settings panel controls the core configuration of your restaurant. From here you can:': 'సెట్టింగ్‌ల ప్యానెల్ మీ రెస్టారెంట్ యొక్క ప్రధాన కాన్ఫిగరేషన్‌ను నియంత్రిస్తుంది.ఇక్కడ నుండి మీరు:',
    'Change the Restaurant Name, Address, and FSSAI number for Bill Printing.': 'బిల్ ప్రింటింగ్ కోసం రెస్టారెంట్ పేరు, చిరునామా మరియు FSSAI నంబర్‌ను మార్చండి.',
    'Configure Tax Rates (GST, CGST, SGST).': 'పన్ను రేట్లు (GST, CGST, SGST) కాన్ఫిగర్ చేయండి.',
    'Add/Remove Printers for KOTs and Bills.': 'KOTలు మరియు బిల్లుల కోసం ప్రింటర్‌లను జోడించండి/తీసివేయండి.',
