    'Software Update Available': 'மென்பொருள் புதுப்பிப்பு கிடைக்கிறது',
    'A new version of MS Billing is ready to install': 'MS பில்லிங்கின் புதிய பதிப்பு நிறுவத் தயாராக உள்ளது',
    'We have downloaded the latest version of MS Billing in the background. To apply these updates and ensure optimal performance, the application needs to restart.': 'MS பில்லிங்கின் சமீபத்திய பதிப்பை பின்னணியில் பதிவிறக்கம் செய்துள்ளோம்.இந்தப் புதுப்பிப்புகளைப் பயன்படுத்தவும், சிறந்த செயல்திறனை உறுதிப்படுத்தவும், பயன்பாட்டை மறுதொடக்கம் செய்ய வேண்டும்.',
    'Performance and stability improvements': 'செயல்திறன் மற்றும் நிலைத்தன்மை மேம்பாடுகள்',
    'Enhanced security protocols': 'மேம்படுத்தப்பட்ட பாதுகாப்பு நெறிமுறைகள்',
    'Latest features and bug fixes': 'சமீபத்திய அம்சங்கள் மற்றும் பிழை திருத்தங்கள்',
    'Restart and Install Update': 'புதுப்பிப்பை மறுதொடக்கம் செய்து நிறுவவும்',
    'The restart will take approximately 10 seconds.': 'மறுதொடக்கம் தோராயமாக 10 வினாடிகள் எடுக்கும்.',
    'MS Billing Documentation': 'MS பில்லிங் ஆவணம்',
    'Comprehensive guide to managing your restaurant': 'உங்கள் உணவகத்தை நிர்வகிப்பதற்கான விரிவான வழிகாட்டி',
    'Welcome to MS Billing': 'MS பில்லிங்கிற்கு வரவேற்கிறோம்',
    'MS Billing is a next-generation Restaurant Management POS designed for speed, accuracy, and ease of use. Whether you are running a small cafe or a multi-floor fine dining restaurant, this guide will help you get the most out of your terminal.': 'MS பில்லிங் என்பது வேகம், துல்லியம் மற்றும் பயன்பாட்டின் எளிமைக்காக வடிவமைக்கப்பட்ட அடுத்த தலைமுறை உணவக மேலாண்மை POS ஆகும்.நீங்கள் ஒரு சிறிய ஓட்டலை நடத்தினாலும் அல்லது பல மாடி ஃபைன் டைனிங் உணவகத்தை நடத்தினாலும், இந்த வழிகாட்டி உங்கள் டெர்மினலில் இருந்து அதிக பலனைப் பெற உதவும்.',
    'Quick Setup': 'விரைவு அமைவு',
    'Create your spaces (Tables, Cabins, Sofas) in Floor Management.': 'மாடி நிர்வாகத்தில் உங்கள் இடைவெளிகளை (டேபிள்கள், கேபின்கள், சோஃபாக்கள்) உருவாக்கவும்.',
    'Add your categories and food items in the Menu Management.': 'மெனு நிர்வாகத்தில் உங்கள் வகைகளையும் உணவுப் பொருட்களையும் சேர்க்கவும்.',
    'Register your staff members with Face AI for seamless attendance.': 'தடையற்ற வருகைக்காக உங்கள் பணியாளர்களை Face AI உடன் பதிவு செய்யவும்.',
    'You are ready to start taking orders!': 'ஆர்டர்களை எடுக்கத் தயாராக உள்ளீர்கள்!',
    'Keyboard Shortcuts': 'விசைப்பலகை குறுக்குவழிகள்',
    'Zoom In': 'பெரிதாக்கவும்',
    'Ctrl + =': 'Ctrl + =',
    'Zoom Out': 'பெரிதாக்கவும்',
