    'A new version of MS Billing is ready to install': 'MS ಬಿಲ್ಲಿಂಗ್‌ನ ಹೊಸ ಆವೃತ್ತಿಯು ಸ್ಥಾಪಿಸಲು ಸಿದ್ಧವಾಗಿದೆ',
    'We have downloaded the latest version of MS Billing in the background. To apply these updates and ensure optimal performance, the application needs to restart.': 'ನಾವು ಹಿನ್ನೆಲೆಯಲ್ಲಿ MS ಬಿಲ್ಲಿಂಗ್‌ನ ಇತ್ತೀಚಿನ ಆವೃತ್ತಿಯನ್ನು ಡೌನ್‌ಲೋಡ್ ಮಾಡಿದ್ದೇವೆ.ಈ ನವೀಕರಣಗಳನ್ನು ಅನ್ವಯಿಸಲು ಮತ್ತು ಅತ್ಯುತ್ತಮ ಕಾರ್ಯಕ್ಷಮತೆಯನ್ನು ಖಚಿತಪಡಿಸಿಕೊಳ್ಳಲು, ಅಪ್ಲಿಕೇಶನ್ ಅನ್ನು ಮರುಪ್ರಾರಂಭಿಸುವ ಅಗತ್ಯವಿದೆ.',
    'Performance and stability improvements': 'ಕಾರ್ಯಕ್ಷಮತೆ ಮತ್ತು ಸ್ಥಿರತೆಯ ಸುಧಾರಣೆಗಳು',
    'Enhanced security protocols': 'ಸುಧಾರಿತ ಭದ್ರತಾ ಪ್ರೋಟೋಕಾಲ್‌ಗಳು',
    'Latest features and bug fixes': 'ಇತ್ತೀಚಿನ ವೈಶಿಷ್ಟ್ಯಗಳು ಮತ್ತು ದೋಷ ಪರಿಹಾರಗಳು',
    'Restart and Install Update': 'ನವೀಕರಣವನ್ನು ಮರುಪ್ರಾರಂಭಿಸಿ ಮತ್ತು ಸ್ಥಾಪಿಸಿ',
    'The restart will take approximately 10 seconds.': 'ಮರುಪ್ರಾರಂಭವು ಸುಮಾರು 10 ಸೆಕೆಂಡುಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳುತ್ತದೆ.',
    'MS Billing Documentation': 'MS ಬಿಲ್ಲಿಂಗ್ ಡಾಕ್ಯುಮೆಂಟೇಶನ್',
    'Comprehensive guide to managing your restaurant': 'ನಿಮ್ಮ ರೆಸ್ಟೋರೆಂಟ್ ಅನ್ನು ನಿರ್ವಹಿಸಲು ಸಮಗ್ರ ಮಾರ್ಗದರ್ಶಿ',
    'Welcome to MS Billing': 'MS ಬಿಲ್ಲಿಂಗ್‌ಗೆ ಸುಸ್ವಾಗತ',
    'MS Billing is a next-generation Restaurant Management POS designed for speed, accuracy, and ease of use. Whether you are running a small cafe or a multi-floor fine dining restaurant, this guide will help you get the most out of your terminal.': 'MS ಬಿಲ್ಲಿಂಗ್ ವೇಗ, ನಿಖರತೆ ಮತ್ತು ಬಳಕೆಯ ಸುಲಭತೆಗಾಗಿ ವಿನ್ಯಾಸಗೊಳಿಸಲಾದ ಮುಂದಿನ-ಪೀಳಿಗೆಯ ರೆಸ್ಟೋರೆಂಟ್ ನಿರ್ವಹಣೆ POS ಆಗಿದೆ.ನೀವು ಸಣ್ಣ ಕೆಫೆ ಅಥವಾ ಬಹು ಮಹಡಿ ಫೈನ್ ಡೈನಿಂಗ್ ರೆಸ್ಟೋರೆಂಟ್ ಅನ್ನು ನಡೆಸುತ್ತಿರಲಿ, ನಿಮ್ಮ ಟರ್ಮಿನಲ್‌ನಿಂದ ಹೆಚ್ಚಿನದನ್ನು ಪಡೆಯಲು ಈ ಮಾರ್ಗದರ್ಶಿ ನಿಮಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ.',
    'Quick Setup': 'ತ್ವರಿತ ಸೆಟಪ್',
    'Create your spaces (Tables, Cabins, Sofas) in Floor Management.': 'ಮಹಡಿ ನಿರ್ವಹಣೆಯಲ್ಲಿ ನಿಮ್ಮ ಸ್ಥಳಗಳನ್ನು (ಟೇಬಲ್‌ಗಳು, ಕ್ಯಾಬಿನ್‌ಗಳು, ಸೋಫಾಗಳು) ರಚಿಸಿ.',
    'Add your categories and food items in the Menu Management.': 'ಮೆನು ನಿರ್ವಹಣೆಯಲ್ಲಿ ನಿಮ್ಮ ವರ್ಗಗಳು ಮತ್ತು ಆಹಾರ ಪದಾರ್ಥಗಳನ್ನು ಸೇರಿಸಿ.',
    'Register your staff members with Face AI for seamless attendance.': 'ತಡೆರಹಿತ ಹಾಜರಾತಿಗಾಗಿ ನಿಮ್ಮ ಸಿಬ್ಬಂದಿ ಸದಸ್ಯರನ್ನು ಫೇಸ್ AI ನೊಂದಿಗೆ ನೋಂದಾಯಿಸಿ.',
    'You are ready to start taking orders!': 'ನೀವು ಆದೇಶಗಳನ್ನು ತೆಗೆದುಕೊಳ್ಳಲು ಸಿದ್ಧರಾಗಿರುವಿರಿ!',
