    'Ctrl + -': 'Ctrl + -',
    'Reset Zoom': 'ಜೂಮ್ ಅನ್ನು ಮರುಹೊಂದಿಸಿ',
    'Ctrl + 0': 'Ctrl + 0',
    'Full Screen': 'ಪೂರ್ಣ ಪರದೆ',
