    'Billing & Orders': 'ಬಿಲ್ಲಿಂಗ್ ಮತ್ತು ಆರ್ಡರ್‌ಗಳು',
    'Taking an Order': 'ಆದೇಶವನ್ನು ತೆಗೆದುಕೊಳ್ಳುವುದು',
    'To take a new order, navigate to the': 'ಹೊಸ ಆರ್ಡರ್ ತೆಗೆದುಕೊಳ್ಳಲು, ಗೆ ನ್ಯಾವಿಗೇಟ್ ಮಾಡಿ',
    'tab.                       Select the items from the menu, adjust quantities using the + and - buttons, and click': 'ಟ್ಯಾಬ್. ಮೆನುವಿನಿಂದ ಐಟಂಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ, + ಮತ್ತು - ಬಟನ್‌ಗಳನ್ನು ಬಳಸಿಕೊಂಡು ಪ್ರಮಾಣಗಳನ್ನು ಹೊಂದಿಸಿ ಮತ್ತು ಕ್ಲಿಕ್ ಮಾಡಿ',
    'Save KOT': 'KOT ಉಳಿಸಿ',
    'to send it to the kitchen.': 'ಅದನ್ನು ಅಡಿಗೆಗೆ ಕಳುಹಿಸಲು.',
    'Use the Search Bar to quickly find items by name.': 'ಹೆಸರಿನ ಮೂಲಕ ಐಟಂಗಳನ್ನು ತ್ವರಿತವಾಗಿ ಹುಡುಕಲು ಹುಡುಕಾಟ ಪಟ್ಟಿಯನ್ನು ಬಳಸಿ.',
    'Filter items by clicking on the category tabs on the left.': 'ಎಡಭಾಗದಲ್ಲಿರುವ ವರ್ಗ ಟ್ಯಾಬ್‌ಗಳ ಮೇಲೆ ಕ್ಲಿಕ್ ಮಾಡುವ ಮೂಲಕ ಐಟಂಗಳನ್ನು ಫಿಲ್ಟರ್ ಮಾಡಿ.',
    'Click on a cart item to add special instructions (e.g., "Less spicy").': 'ವಿಶೇಷ ಸೂಚನೆಗಳನ್ನು ಸೇರಿಸಲು ಕಾರ್ಟ್ ಐಟಂ ಅನ್ನು ಕ್ಲಿಕ್ ಮಾಡಿ (ಉದಾ., "ಕಡಿಮೆ ಮಸಾಲೆ").',
