    'As an Admin, you can add new Spaces (like "AC Section", "Rooftop") and configure how many tables belong to each space from the Settings menu.': 'ನಿರ್ವಾಹಕರಾಗಿ, ನೀವು ಹೊಸ ಸ್ಪೇಸ್‌ಗಳನ್ನು ಸೇರಿಸಬಹುದು ("AC ವಿಭಾಗ", "ಮೇಲ್ಛಾವಣಿ" ನಂತಹ) ಮತ್ತು ಸೆಟ್ಟಿಂಗ್‌ಗಳ ಮೆನುವಿನಿಂದ ಪ್ರತಿ ಸ್ಪೇಸ್‌ಗೆ ಎಷ್ಟು ಕೋಷ್ಟಕಗಳು ಸೇರಿವೆ ಎಂಬುದನ್ನು ಕಾನ್ಫಿಗರ್ ಮಾಡಬಹುದು.',
    'Staff & AI Attendance': 'ಸಿಬ್ಬಂದಿ ಮತ್ತು AI ಹಾಜರಾತಿ',
    'Facial Recognition Setup': 'ಮುಖ ಗುರುತಿಸುವಿಕೆ ಸೆಟಪ್',
