    'Welcome to MS Billing': 'MS ബില്ലിംഗിലേക്ക് സ്വാഗതം',
    'MS Billing is a next-generation Restaurant Management POS designed for speed, accuracy, and ease of use. Whether you are running a small cafe or a multi-floor fine dining restaurant, this guide will help you get the most out of your terminal.': 'വേഗതയ്ക്കും കൃത്യതയ്ക്കും ഉപയോഗ എളുപ്പത്തിനും വേണ്ടി രൂപകൽപ്പന ചെയ്ത ഒരു അടുത്ത തലമുറ റെസ്റ്റോറൻ്റ് മാനേജ്മെൻ്റ് POS ആണ് MS ബില്ലിംഗ്.നിങ്ങൾ ഒരു ചെറിയ കഫേ അല്ലെങ്കിൽ മൾട്ടി-ഫ്ലോർ ഫൈൻ ഡൈനിംഗ് റെസ്റ്റോറൻ്റ് നടത്തുകയാണെങ്കിലും, നിങ്ങളുടെ ടെർമിനൽ പരമാവധി പ്രയോജനപ്പെടുത്താൻ ഈ ഗൈഡ് നിങ്ങളെ സഹായിക്കും.',
