    'Create your spaces (Tables, Cabins, Sofas) in Floor Management.': 'ഫ്ലോർ മാനേജ്‌മെൻ്റിൽ നിങ്ങളുടെ സ്‌പെയ്‌സുകൾ (ടേബിളുകൾ, ക്യാബിനുകൾ, സോഫകൾ) സൃഷ്‌ടിക്കുക.',
    'Add your categories and food items in the Menu Management.': 'മെനു മാനേജ്മെൻ്റിൽ നിങ്ങളുടെ വിഭാഗങ്ങളും ഭക്ഷണ ഇനങ്ങളും ചേർക്കുക.',
